/* Generates js/bundled-catalog.js from https://models.dev/api.json
   Run:  node tools/build-bundle.js
   Produces a compact offline fallback: every provider's metadata plus the
   models of the providers OpenCode documents in its own guides. */
const fs = require('fs');
const path = require('path');

const SRC = 'https://models.dev/api.json';
const OUT = path.join(__dirname, '..', 'js', 'bundled-catalog.js');

/** Providers OpenCode names in its documentation, in display order. */
const PRIORITY = [
  'opencode', 'anthropic', 'openai', 'google', 'google-vertex', 'azure',
  'amazon-bedrock', 'openrouter', 'xai', 'github-copilot', 'lmstudio',
  'ollama', 'vllm', 'deepinfra', 'groq', 'cerebras', 'fireworks-ai',
  'mistral', 'cohere', 'perplexity', 'vercel', 'amazon-bedrock', 'zhipuai',
  'zai', 'moonshotai', 'inception', 'opencode-zen'
];

const MAX_MODELS_PER_PROVIDER = 30;

async function main() {
  process.stdout.write('fetching models.dev ... ');
  const res = await fetch(SRC);
  if (!res.ok) throw new Error('HTTP ' + res.status);
  const raw = await res.json();
  console.log(Object.keys(raw).length + ' providers');

  const out = {};
  let modelCount = 0;

  for (const [pid, p] of Object.entries(raw)) {
    const meta = {
      name: p.name || pid,
      env: Array.isArray(p.env) ? p.env : (p.env ? [p.env] : []),
      npm: p.npm || '',
      doc: p.doc || ''
    };

    const all = p.models && typeof p.models === 'object' ? Object.entries(p.models) : [];
    const ranked = all.sort((a, b) => {
      // newer release date first, then richer context window
      const da = (a[1] && a[1].release_date) || '';
      const db = (b[1] && b[1].release_date) || '';
      if (da !== db) return db.localeCompare(da);
      const ca = (a[1] && a[1].limit && a[1].limit.context) || 0;
      const cb = (b[1] && b[1].limit && b[1].limit.context) || 0;
      return cb - ca;
    });

    const isPriority = PRIORITY.includes(pid);
    const slice = isPriority ? ranked.slice(0, MAX_MODELS_PER_PROVIDER) : ranked.slice(0, 6);

    if (!slice.length) { out[pid] = meta; continue; }

    const models = {};
    for (const [mid, m] of slice) {
      models[mid] = {
        name: m.name || mid,
        fam: m.family || '',
        rel: m.release_date || '',
        reasoning: !!m.reasoning,
        ropts: m.reasoning_options || null,
        tools: !!m.tool_call,
        struct: !!m.structured_output,
        attach: !!m.attachment,
        in: (m.modalities && m.modalities.input) || [],
        out: (m.modalities && m.modalities.output) || [],
        ctx: (m.limit && m.limit.context) || 0,
        maxOut: (m.limit && m.limit.output) || 0,
        cin: (m.cost && m.cost.input) != null ? m.cost.input : null,
        cout: (m.cost && m.cost.output) != null ? m.cost.output : null,
        cid: m.canonical_model_id || ''
      };
    }
    modelCount += Object.keys(models).length;
    out[pid] = Object.assign(meta, {
      models,
      total: all.length,          // how many the live catalog holds
      bundled: slice.length
    });
  }

  const payload = {
    source: SRC,
    fetched: new Date().toISOString(),
    providers: out
  };

  const js = '/* Offline fallback for the models.dev catalog.\n'
    + '   Generated by tools/build-bundle.js — do not edit by hand. */\n'
    + 'window.OCM_BUNDLED_CATALOG = '
    + JSON.stringify(payload) + ';\n';

  fs.writeFileSync(OUT, js);
  const kb = Math.round(Buffer.byteLength(js) / 1024);
  console.log('wrote js/bundled-catalog.js — ' + kb + ' KB, ' +
    Object.keys(out).length + ' providers, ' + modelCount + ' models');
}

main().catch(e => { console.error('\nFAILED: ' + e.message); process.exit(1); });